python3 -B -c 'import json,base64,hashlib;from pathlib import Path;P=Path;out={"connectors":{},"cards":{}}
for c in sorted(P("/sys/class/drm").glob("card*-*")):
 d={"path":str(c.resolve())}
 for n in ["status","enabled","dpms","modes","connector_id"]:
  p=c/n
  if p.exists():
   try:d[n]=p.read_text().strip()
   except OSError as e:d[n]={"error":str(e)}
 p=c/"edid"
 if p.exists():
  b=p.read_bytes();d["edid"]={"bytes":len(b),"sha256":hashlib.sha256(b).hexdigest(),"base64":base64.b64encode(b).decode()}
 out["connectors"][c.name]=d
for c in sorted(P("/sys/class/drm").glob("card[0-9]")):
 out["cards"][c.name]={"device":str((c/"device").resolve()),"driver":str((c/"device/driver").resolve())}
print(json.dumps(out,indent=2))'

python3 -B -c 'import json;from pathlib import Path;P=Path;out={}
paths=[P("/proc/fb")]+list(P("/sys/kernel/debug/dri").glob("*/state"))+list(P("/sys/kernel/debug/dri").glob("*/name"))+list(P("/sys/kernel/debug/dri").glob("*/clients"))
for f in P("/sys/class/graphics").glob("fb*"):
 paths.extend(f/n for n in ["name","modes","mode","virtual_size","bits_per_pixel","stride","blank"])
for p in paths:
 if p.exists():
  try:out[str(p)]=p.read_text()
  except OSError as e:out[str(p)]={"error":str(e)}
p=P("/sys/kernel/debug/clk/clk_summary")
if p.exists():out["display_clock_summary"]=[l for l in p.read_text().splitlines() if any(s in l.lower() for s in ["dpll","dpdma","dp_video","dp_audio","dp_ref"])]
print(json.dumps(out,indent=2))'

python3 -B -c 'import json,shutil,subprocess;from pathlib import Path;P=Path;out={"tools":{n:shutil.which(n) for n in ["modetest","kmsprint","fbset","xrandr","xdpyinfo","weston","gst-launch-1.0","gst-inspect-1.0","python3"]},"display_processes":[],"device_owners":[],"commands":[]}
for p in P("/proc").iterdir():
 if not p.name.isdigit():continue
 try:
  comm=(p/"comm").read_text().strip()
  if any(s in comm.lower() for s in ["weston","xorg","xwayland","wayland","matchbox","qt","kms","gst"]):out["display_processes"].append({"pid":int(p.name),"comm":comm})
  owned=[str(f.resolve()) for f in (p/"fd").iterdir() if str(f.resolve()) in ["/dev/dri/card0","/dev/fb0"]]
  if owned:out["device_owners"].append({"pid":int(p.name),"comm":comm,"devices":owned})
 except OSError:pass
for c in [["systemctl","show","dfx-mgr.service","weston.service","display-manager.service","-p","Id","-p","LoadState","-p","ActiveState","-p","SubState","-p","MainPID"],["systemctl","--failed","--no-pager"],["xmutil","listapps"]]:
 r=subprocess.run(c,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,timeout=20);out["commands"].append({"argv":c,"rc":r.returncode,"stdout":r.stdout,"stderr":r.stderr})
print(json.dumps(out,indent=2))'
